insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_musicstudies_v1'
from (values
('117.314.c.1.A',2,'In a music studies class, students stream a famous jazz quartet and then attend a live student jam. They are experiencing what?','["Exemplary music through technology and live performance", "Stage carpentry", "Ticket scalping", "Lobby design"]'::jsonb,0,'Both formats supply musical models.','original'),
('117.314.c.1.A',2,'Why do producers study classic recordings?','["To memorize prices", "To learn how skilled artists shape sound and style", "To avoid listening", "To skip practice"]'::jsonb,1,'Classics model good technique.','original'),
('117.314.c.1.B',2,'On a pop track, the lead vocal carries the tune while keyboards and bass fill in chords. The lead vocal is the ___ part.','["Percussive", "Meter", "Melodic", "Silent"]'::jsonb,2,'The lead line is the melody.','original'),
('117.314.c.1.B',2,'Notes played together beneath a melody create what?','["Volume only", "Silence", "Tempo", "Harmony"]'::jsonb,3,'Harmony supports the melody.','original'),
('117.314.c.1.C',2,'The distance in pitch from C to the next higher C is an ___.','["Octave", "Second", "Third", "Fourth"]'::jsonb,0,'An octave spans eight scale degrees.','original'),
('117.314.c.1.C',2,'Which chord contains a root, a third and a fifth?','["A tie", "A triad", "A rest", "An accent"]'::jsonb,1,'A triad stacks thirds.','original'),
('117.314.c.1.D',2,'In a song with four steady beats per measure, which meter is being used?','["9/8", "2/2 only", "4/4", "3/4"]'::jsonb,2,'Four beats per measure indicates 4/4.','original'),
('117.314.c.1.D',2,'Counting a beat aloud as 1 and 2 and 3 and 4 and shows what?','["A clef", "A key signature", "A chord symbol", "A counting system that includes the subdivision"]'::jsonb,3,'Counting syllables mark eighth-note subdivisions.','original'),
('117.314.c.1.E',2,'Which is an element of music?','["Melody", "Lighting grid", "Poster", "Costume"]'::jsonb,0,'Melody is a core element.','original'),
('117.314.c.1.E',2,'A symbol such as mf or ff tells a performer about what?','["Clef", "Dynamics", "Key", "Meter"]'::jsonb,1,'Dynamic markings show volume.','original'),
('117.314.c.1.F',2,'Which habit helps a studio musician protect their ears during long sessions?','["Never resting", "Turning headphones up", "Taking listening breaks and keeping monitor volume moderate", "Wearing no protection near loud amps"]'::jsonb,2,'Moderate volume and breaks prevent hearing damage.','original'),
('117.314.c.1.F',2,'Why should a keyboardist adjust bench height and wrist position?','["To play softer", "To change keys", "To read faster", "To reduce strain and avoid injury"]'::jsonb,3,'Ergonomics prevent overuse injury.','original'),
('117.314.c.2.A',2,'A student reads chord charts in one assignment and manipulates audio loops in another. This shows what?','["Reading notation systems or manipulating sounds as the course requires", "Avoiding sound", "Memorizing menus", "Selling music"]'::jsonb,0,'Music studies includes diverse tools.','original'),
('117.314.c.2.A',2,'Which could be a notation system used in a music studies course?','["Weather map", "Lead sheet or tablature", "Bus schedule", "Recipe card"]'::jsonb,1,'Different notations suit different instruments.','original'),
('117.314.c.2.B',3,'A student notates a rhythm in 6/8 and records it with a drum machine. What is she doing?','["Tuning a violin", "Painting a mural", "Notating and producing a rhythmic pattern", "Printing tickets"]'::jsonb,2,'Notation and recording work together.','original'),
('117.314.c.2.B',3,'Which meter is considered simple?','["6/8", "12/8", "9/8", "2/4"]'::jsonb,3,'Simple meters divide each beat into two.','original'),
('117.314.c.2.C',2,'The marking staccato tells a performer to do what?','["Play the notes short and detached", "Play louder", "Play slower", "Hold the notes long"]'::jsonb,0,'Staccato means detached.','original'),
('117.314.c.2.C',2,'The Italian word adagio indicates what?','["A repeat", "A slow tempo", "A fast tempo", "A loud dynamic"]'::jsonb,1,'Adagio means slow.','original'),
('117.314.c.2.D',3,'A student producing a track in D major notes that two sharps belong in the key signature. Which are they?','["None", "B-flat and E-flat", "F-sharp and C-sharp", "G-sharp and D-sharp"]'::jsonb,2,'D major has F# and C#.','original'),
('117.314.c.2.D',3,'What does knowing a song''s mode help a producer decide?','["Which microphones cost less", "Which seats are open", "Which lights to buy", "Which scale notes and mood fit the song"]'::jsonb,3,'Mode defines the scale and feel.','original'),
('117.314.c.2.E',3,'A student uses a digital audio workstation to record a vocal and layer harmonies. This is which skill?','["Using technology for recording and production", "Ignoring sound", "Selling merchandise", "Hand-copying scores only"]'::jsonb,0,'A DAW is a production tool.','original'),
('117.314.c.2.E',3,'Why should a recording be saved in multiple versions?','["To change the key", "So earlier takes can be recovered if edits go wrong", "To use up storage", "To speed up the song"]'::jsonb,1,'Versioning protects work.','original'),
('117.314.c.3.A',3,'A producer chooses a warm tone for a ballad and a bright, punchy tone for a dance track. She is demonstrating what?','["No plan", "Poor mixing", "Characteristic sounds appropriate for each genre", "Random choices"]'::jsonb,2,'Sound choices fit style.','original'),
('117.314.c.3.A',3,'Which tool shapes the tone of a recorded instrument?','["A poster", "A seating chart", "A ticket", "Equalization"]'::jsonb,3,'EQ adjusts frequency balance.','original'),
('117.314.c.3.B',3,'A student prepares a set including a blues, a bossa nova and a pop ballad. She is building what?','["A repertoire representing a variety of styles", "A silent concert", "A single-style set", "A lecture"]'::jsonb,0,'Variety shows range.','original'),
('117.314.c.3.B',3,'Which choice would add variety to a performance repertoire?','["Repeating one song", "Pieces from different cultures and time periods", "Playing only the intro", "Skipping rehearsals"]'::jsonb,1,'Diverse styles broaden skills.','original'),
('117.314.c.3.C',3,'A student lays down a drum track and checks it against a click to make sure the rhythm is steady. She is demonstrating what?','["Loud dynamics", "Random pitch", "Rhythmic accuracy", "Poor timing"]'::jsonb,2,'A click confirms steady timing.','original'),
('117.314.c.3.C',3,'Legato articulation means notes are what?','["Very short", "Accented", "Silent", "Smooth and connected"]'::jsonb,3,'Legato is connected.','original'),
('117.314.c.3.D',3,'A performer builds a gradual crescendo over a verse and a soft ending for contrast. She is demonstrating what?','["Dynamics and phrasing", "Silence only", "Wrong notes", "A key change"]'::jsonb,0,'Dynamics shape the line.','original'),
('117.314.c.3.D',3,'What is a musical phrase?','["One single note", "A group of notes that forms a complete musical idea", "A rest only", "A page number"]'::jsonb,1,'Phrases are musical sentences.','original'),
('117.314.c.3.E',3,'A guitarist tunes each string with a tuner before a recording session. She is attending to what?','["Tempo", "Notation", "Intonation", "Meter"]'::jsonb,2,'Tuning ensures correct pitch.','original'),
('117.314.c.3.E',3,'Singing slightly flat throughout a song is a problem of what?','["Form", "Rests", "Rhythm", "Intonation"]'::jsonb,3,'Pitch accuracy is intonation.','original'),
('117.314.c.3.F',3,'What is a good technique for an informal coffeehouse performance?','["Adapting your set and stage presence to a relaxed audience", "Ignoring the crowd", "Refusing to speak", "Leaving mid-song"]'::jsonb,0,'Informal concerts allow flexibility.','original'),
('117.314.c.3.F',3,'What is one technique for a formal recital?','["Improvising the order every time", "Dressing professionally and following a prepared program", "Wearing anything", "Arriving late"]'::jsonb,1,'Formal concerts follow conventions.','original'),
('117.314.c.4.A',3,'A student creates a four-bar melody from a scale and builds a rhythm for it. She is doing what?','["Selling tickets", "Buying a score", "Creating an original musical phrase", "Copying a song"]'::jsonb,2,'Composition begins with phrases.','original'),
('117.314.c.4.A',3,'Which approach helps create a memorable melody?','["Never repeating", "Using random notes", "Using no rhythm", "Repeating and varying a short motif"]'::jsonb,3,'Repetition with variation builds memorability.','original'),
('117.314.c.4.B',3,'A producer records a new riff on her phone and later writes it in notation. She is doing what?','["Recording and notating an original phrase", "Deleting files", "Avoiding documentation", "Erasing music"]'::jsonb,0,'Both recording and notation preserve ideas.','original'),
('117.314.c.4.B',3,'Which tool lets a composer write music on a staff and hear it played back?','["A coupon", "Notation software", "A ruler", "A stopwatch"]'::jsonb,1,'Software supports notation and playback.','original'),
('117.314.c.5.A',3,'A student compares reggae and country music by rhythm, instruments and cultural roots. She is doing what?','["Painting", "Ordering food", "Comparing and contrasting music by genre and culture", "Counting seats"]'::jsonb,2,'Comparison uses musical and cultural features.','original'),
('117.314.c.5.A',3,'Which pair of terms describes historical periods?','["Treble and bass", "Allegro and piano", "Major and minor", "Baroque and Romantic"]'::jsonb,3,'These are eras in music history.','original'),
('117.314.c.5.B',2,'Which is a vocation in the music business?','["Recording engineer", "Plumber", "Surveyor", "Roofer"]'::jsonb,0,'Engineering is a music career.','original'),
('117.314.c.5.B',2,'Someone who plays guitar for fun with friends has a music ___.','["Degree", "Avocation", "Vocation", "License"]'::jsonb,1,'An avocation is a hobby.','original'),
('117.314.c.5.C',2,'Why do people sing at birthday celebrations?','["It ends traditions", "It prevents speech", "Music is used to mark and share special occasions", "It avoids joy"]'::jsonb,2,'Songs mark celebrations.','original'),
('117.314.c.5.C',2,'A protest song is an example of music used to do what?','["Hide ideas", "Replace laws", "Stop speech", "Express beliefs and unite people"]'::jsonb,3,'Songs can express and unite.','original'),
('117.314.c.5.D',3,'Calculating the length of a song in measures from its tempo connects music to which subject?','["Mathematics", "Cooking", "Gym", "Welding"]'::jsonb,0,'Music uses arithmetic.','original'),
('117.314.c.5.D',3,'Studying how a microphone captures sound connects music to which discipline?','["Painting only", "Physics", "Typing", "Geography only"]'::jsonb,1,'Sound capture involves physics.','original'),
('117.314.c.5.E',3,'Using a sample from another artist''s recording without permission can raise what issue?','["A seating issue", "A tempo issue", "Copyright and ethical concerns", "A tuning issue"]'::jsonb,2,'Using music requires permission.','original'),
('117.314.c.5.E',3,'Streaming has changed how artists earn income because listeners now pay what way?','["Through coupons only", "Only by buying vinyl", "By paying nothing ever", "Through subscriptions and small per-play payments"]'::jsonb,3,'Streaming changed the economics.','original'),
('117.314.c.5.F',3,'A student creates a social media page to share performance clips and book gigs. She is using what?','["A tool for career preparation", "A time signature", "A cadence", "A clef"]'::jsonb,0,'Social media promotes artists.','original'),
('117.314.c.5.F',3,'What is a useful tool for a young musician seeking a college program?','["A menu", "A recorded audition portfolio", "A bus map", "A calendar of sales"]'::jsonb,1,'Portfolios show skills.','original'),
('117.314.c.6.A',2,'At a student showcase, good audience behavior is to do what?','["Talk through songs", "Record loudly aloud", "Silence phones and applaud politely", "Leave during sets"]'::jsonb,2,'Etiquette respects performers.','original'),
('117.314.c.6.A',2,'As a performer, good etiquette includes what?','["Complaining onstage", "Ignoring others", "Leaving early", "Thanking the audience and supporting other acts"]'::jsonb,3,'Courtesy supports a positive event.','original'),
('117.314.c.6.B',3,'A class builds a checklist with tone, rhythm, creativity and stage presence to judge a performance. This is what?','["Designing criteria for informed judgments", "Copying", "Guessing", "Skipping evaluation"]'::jsonb,0,'Criteria guide judgments.','original'),
('117.314.c.6.B',3,'Which feedback applies criteria?','["Not sure", "The groove stayed steady, but the vocal was sharp in the chorus", "I liked it", "Nope"]'::jsonb,1,'Specific comments apply criteria.','original'),
('117.314.c.6.C',3,'A student records her sets, watches them back and tracks goals in a notebook. She is developing what?','["A concert flyer", "A seat map", "A process for self-evaluation", "A ticket booth"]'::jsonb,2,'Review and goals drive improvement.','original'),
('117.314.c.6.C',3,'Which tool supports a musician''s artistic growth?','["A menu", "A coupon", "A parking pass", "A weekly practice log"]'::jsonb,3,'Logs track progress.','original'),
('117.314.c.6.D',3,'A student compares her cover of a song to the original recording and lists differences in feel and tone. She is doing what?','["Evaluating a performance against an exemplary model", "Deleting both", "Skipping the lesson", "Ignoring the original"]'::jsonb,0,'Comparison with models guides growth.','original'),
('117.314.c.6.D',3,'After comparing to a model, a musician should do what next?','["Ignore the model", "Pick one or two specific areas to practice", "Quit music", "Blame equipment"]'::jsonb,1,'Evaluation should lead to action.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
